				\setlength{\oddsidemargin}{-69pt}
				\begin{document}$$l_{i,j} = - \log \frac{{{{{\mathrm{exp}}}}(cos(z_i,z_j)/\tau )}}{{\mathop {\sum }\nolimits_{k = 1}^{2N} {{{\mathrm{exp}}}}(cos(z_i,z_k)/\tau )}}$$\end{document}li,j=−logexp(cos(zi,zj)/τ)∑k=12Nexp(cos(zi,zk)/τ)

